import React from 'react'

function Task(props) {

    const { libelle, complete, del, handleDelete, handleComplete } = props
    // console.log(props)
    return (
        <>
            <div className='task-item'>
                <span className={`task-name ${complete ? 'complete' : ''}`}>
                    {libelle}
                </span>
                <buton className='task-action-btn complete-btn' onClick={handleComplete}>{/*complete ? handleUndo : */}
                    {complete ? 'Undo' : 'Complete'}
                </buton>
                <buton className='task-action-btn delete-btn' onClick={handleDelete}>
                    delete
                </buton>
            </div>
        </>
    )
}

export default Task
